geelooy/ai/css/mobile/shell.css.content:
/* B"H — mobile shell: side panels become real reachable rows, not overlays */
@media (max-width: 680px) {
  html, body { min-width: 0; width: 100%; height: 100%; overflow: hidden; }
  .container {
    width: 100vw !important;
    height: 100dvh !important;
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) !important;
    grid-template-rows: auto minmax(0, 1fr) auto !important;
    grid-template-areas: "left" "main" "right" !important;
    gap: 6px !important;
    padding: max(6px, env(safe-area-inset-top)) 6px max(6px, env(safe-area-inset-bottom)) !important;
    overflow: hidden !important;
    background: radial-gradient(circle at 50% 0, rgba(34,211,238,.13), transparent 42%), #020711 !important;
  }
  #left-resizer, #right-resizer, #composer-resizer { display: none !important; }
  .main {
    grid-area: main !important;
    min-height: 0 !important;
    min-width: 0 !important;
    border-radius: 18px !important;
    grid-template-rows: auto minmax(0, 1fr) minmax(112px, auto) !important;
    grid-template-areas: "transport" "chat" "composer" !important;
  }
  #transport-status {
    min-height: 36px !important;
    overflow: auto !important;
    white-space: nowrap !important;
  }
  #chat-box { min-height: 0 !important; overflow: auto !important; }
}

geelooy/ai/css/mobile/panels.css.content:
/* B"H — mobile panels: compact reachable top/bottom vessels */
@media (max-width: 680px) {
  .sidebar,
  .automation-panel {
    display: grid !important;
    position: relative !important;
    inset: auto !important;
    min-width: 0 !important;
    width: 100% !important;
    max-width: none !important;
    border-radius: 18px !important;
    overflow: hidden !important;
    z-index: auto !important;
  }
  .sidebar { grid-area: left !important; max-height: 84px !important; grid-template-rows: 72px minmax(0, 1fr) !important; }
  .automation-panel { grid-area: right !important; max-height: 90px !important; grid-template-rows: 76px minmax(0, 1fr) !important; }
  body:not([data-sidebar-collapsed="true"]) .sidebar { max-height: min(42dvh, 360px) !important; }
  body:not([data-automation-collapsed="true"]) .automation-panel { max-height: min(48dvh, 420px) !important; }
  .panel-topbar,
  .sidebar-header {
    min-height: 68px !important;
    padding: 10px 12px !important;
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
  }
  .sidebar::before,
  .automation-panel::before {
    writing-mode: horizontal-tb !important;
    transform: none !important;
    position: static !important;
  }
  .conversation-list,
  .automation-panel > :not(.panel-topbar) {
    min-height: 0 !important;
    overflow: auto !important;
    padding: 10px !important;
  }
  body[data-sidebar-collapsed="true"] .conversation-list,
  body[data-automation-collapsed="true"] .automation-panel > :not(.panel-topbar) { display: none !important; }
  body[data-sidebar-collapsed="true"] .sidebar,
  body[data-automation-collapsed="true"] .automation-panel { max-height: 76px !important; }
  .panel-action-rail,
  .panel-corner-actions { position: static !important; transform: none !important; }
  .right-tabs { overflow-x: auto !important; flex-wrap: nowrap !important; }
  .right-tabs button { flex: 0 0 auto !important; min-width: 104px !important; }
}

geelooy/ai/css/mobile/composer.css.content:
/* B"H — mobile composer: no zoom, real touch targets */
@media (max-width: 680px) {
  .input-area {
    min-height: 112px !important;
    padding: 8px !important;
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) !important;
    grid-template-rows: minmax(54px, 1fr) 54px !important;
    gap: 8px !important;
    border-radius: 18px !important;
  }
  #message-input {
    min-width: 0 !important;
    width: 100% !important;
    min-height: 54px !important;
    font-size: 16px !important;
    line-height: 1.35 !important;
    resize: none !important;
  }
  #send-button,
  .attachment-tools button {
    min-width: 44px !important;
    min-height: 44px !important;
    font-size: 16px !important;
    border-radius: 16px !important;
  }
  #send-button { width: 100% !important; }
  .attachment-tools { position: static !important; display: flex !important; flex-wrap: wrap !important; gap: 8px !important; }
  .live-follow-button { right: 12px !important; bottom: 132px !important; }
}

